Set-Location "c:\git\semio"
function Convert-ToPascalCase([string]$value) {
  if ([string]::IsNullOrWhiteSpace($value)) {
    return $value
  }

  $normalized = $value -replace '[^A-Za-z0-9]+', ' '
  $tokens = $normalized -split '\s+' | Where-Object { $_ }
  if ($tokens.Count -eq 0) {
    return $value
  }

  $builder = [System.Text.StringBuilder]::new()
  foreach ($token in $tokens) {
    $first = $token.Substring(0, 1).ToUpperInvariant()
    $rest = if ($token.Length -gt 1) { $token.Substring(1) } else { '' }
    [void]$builder.Append($first + $rest)
  }
  return $builder.ToString()
}

$typologyFiles = Get-ChildItem "spatial/assets/modelDefinition" -Recurse -File -Filter 'typology.json'
foreach ($file in $typologyFiles) {
  $sourceDir = Split-Path $file.FullName -Parent
  $parentDir = Split-Path $sourceDir -Parent
  $json = Get-Content $file.FullName -Raw | ConvertFrom-Json
  $targetName = Convert-ToPascalCase ([string]$json.label)
  if ([string]::IsNullOrWhiteSpace($targetName)) {
    throw "Missing label for typology: $($file.FullName)"
  }
  $sourceName = Split-Path $sourceDir -Leaf
  if ($sourceName -ceq $targetName) {
    continue
  }

  $targetDir = Join-Path $parentDir $targetName
  if ((Test-Path $targetDir) -and ($sourceDir -ine $targetDir)) {
    throw "Target typology folder already exists: $targetDir"
  }

  if ($sourceDir -ieq $targetDir) {
    $tempDir = Join-Path $parentDir ("__rename__" + [guid]::NewGuid().ToString('N'))
    Move-Item -LiteralPath $sourceDir -Destination $tempDir
    Move-Item -LiteralPath $tempDir -Destination $targetDir
    continue
  }

  Move-Item -LiteralPath $sourceDir -Destination $targetDir
}

Write-Output "Renamed typology folders to PascalCase."

